require "json"
require "net/http"
require "socket"
require "uri"
require "websocket/driver"

class CDPClient
  def initialize(ws_url)
    uri = URI(ws_url)
    @socket = TCPSocket.new(uri.host, uri.port)
    @driver = WebSocket::Driver.client(self)
    @url = ws_url
    @id = 0
    @responses = {}
    @events = []
    @open = false

    @driver.on(:open) { @open = true }
    @driver.on(:message) do |e|
      data = JSON.parse(e.data)
      if data["id"]
        @responses[data["id"]] = data
      else
        @events << data
      end
    end

    @driver.start
    pump until @open
  end

  attr_reader :url

  def write(data)
    @socket.write(data)
  end

  def pump(timeout = 0.05)
    if IO.select([ @socket ], nil, nil, timeout)
      chunk = @socket.readpartial(65536)
      @driver.parse(chunk)
    end
  end

  def call(method, params = {})
    @id += 1
    req_id = @id
    @driver.text(JSON.generate({ id: req_id, method: method, params: params }))
    deadline = Time.now + 15
    until @responses.key?(req_id)
      raise "CDP timeout waiting for #{method}" if Time.now > deadline
      pump
    end
    res = @responses.delete(req_id)
    raise "CDP error in #{method}: #{res['error']}" if res["error"]
    res["result"]
  end

  def drain_events
    pump(0.01) while IO.select([ @socket ], nil, nil, 0.01)
    ev = @events.dup
    @events.clear
    ev
  end

  def wait_for_event(name, timeout: 10)
    deadline = Time.now + timeout
    loop do
      idx = @events.index { |e| e["method"] == name }
      return @events.delete_at(idx) if idx
      raise "Timeout waiting for event #{name}" if Time.now > deadline
      pump
    end
  end

  def eval_js(expr)
    res = call("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true })
    if res["exceptionDetails"]
      raise "JS exception: #{res['exceptionDetails']}"
    end
    res.dig("result", "value")
  end

  def wait_until(desc, timeout: 10)
    deadline = Time.now + timeout
    loop do
      val = yield
      return val if val
      raise "Timeout waiting for: #{desc}" if Time.now > deadline
      pump(0.05)
    end
  end

  def navigate(url)
    drain_events
    call("Page.navigate", { url: url })
    wait_for_event("Page.loadEventFired", timeout: 10)
    wait_until("document ready") { eval_js("document.readyState === 'complete'") }
    sleep 0.2
  end

  def close
    @socket.close rescue nil
  end
end

