  assert_eq false, cdp.eval_js("!!document.getElementById('bot_name')"), "direct /bots/new has no bot_name form"

  puts "8. Deleting Alpha Bot using native confirm() dialog..."
  cdp.navigate("#{BASE}/bots")
  cdp.eval_js("document.querySelector('a[aria-label=\"Edit Alpha Bot\"]').click()")
  cdp.wait_until("on edit page") { cdp.eval_js("document.body.innerText.includes('Delete this chat bot')") }

  cdp.drain_events
  cdp.eval_js("setTimeout(() => Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('Delete this chat bot')).click(), 10)")
  dialog = cdp.wait_for_event("Page.javascriptDialogOpening", timeout: 5)
  assert_eq "confirm", dialog.dig("params", "type"), "native confirm dialog"
  cdp.call("Page.handleJavaScriptDialog", { accept: true })

  cdp.wait_until("back on /bots without Alpha Bot") do
    cdp.eval_js("location.pathname === '/bots' && !document.body.innerText.includes('Alpha Bot')")
  end
  after_delete_text = cdp.eval_js("document.body.innerText")
  assert_eq true, after_delete_text.include?("Add a chat bot"), "Add a chat bot returns after deleting a bot"
  assert_eq false, after_delete_text.include?("reached the limit"), "reached the limit gone after deleting a bot"

  puts "9. Creating replacement Gamma Bot..."
  cdp.eval_js("Array.from(document.querySelectorAll('a')).find(a => a.textContent.includes('Add a chat bot')).click()")
  cdp.wait_until("on /bots/new") { cdp.eval_js("location.pathname === '/bots/new' && !!document.getElementById('bot_name')") }
  cdp.eval_js(<<~JS)
    (() => {
      document.getElementById('bot_name').value = "Gamma Bot";
      document.querySelector('form[action="/bots"]').requestSubmit();
    })()
  JS
  cdp.wait_until("Gamma Bot created") { cdp.eval_js("location.pathname === '/bots' && document.body.innerText.includes('Gamma Bot')") }
  assert_eq false, cdp.eval_js("document.body.innerText.includes('Add a chat bot')"), "at limit again after replacement"
  assert_eq true, cdp.eval_js("document.body.innerText.includes('reached the limit')"), "reached the limit shown again"

  puts "10. Admin sets limit to 0 and verifies admin is unlimited while member keeps existing bots..."
  sign_out.call
  sign_in.call("david@37signals.com")
  cdp.navigate("#{BASE}/account/edit")
  cdp.eval_js(<<~JS)
    (() => {
      const input = document.getElementById('account_settings_bots_per_member');
      input.focus();
      input.value = '0';
      input.dispatchEvent(new Event('input', { bubbles: true }));
      input.dispatchEvent(new Event('change', { bubbles: true }));
    })()
  JS
  cdp.wait_until("flash after setting 0") { cdp.eval_js("!!document.querySelector('.flash')") }
  cdp.navigate("#{BASE}/account/edit")
  assert_eq "0", cdp.eval_js("document.getElementById('account_settings_bots_per_member').value"), "persisted 0"

  cdp.navigate("#{BASE}/bots")
  assert_eq true, cdp.eval_js("document.body.innerText.includes('Add a chat bot')"), "admin still sees Add a chat bot at limit 0"
  cdp.eval_js("Array.from(document.querySelectorAll('a')).find(a => a.textContent.includes('Add a chat bot')).click()")
  cdp.wait_until("admin on /bots/new") { cdp.eval_js("location.pathname === '/bots/new' && !!document.getElementById('bot_name')") }
  cdp.eval_js(<<~JS)
    (() => {
      document.getElementById('bot_name').value = "Admin Unlimited Bot";
      document.querySelector('form[action="/bots"]').requestSubmit();
    })()
  JS
  cdp.wait_until("Admin Unlimited Bot created") { cdp.eval_js("location.pathname === '/bots' && document.body.innerText.includes('Admin Unlimited Bot')") }
  assert_eq true, cdp.eval_js("document.body.innerText.includes('Add a chat bot')"), "admin still sees Add a chat bot after creating"

  sign_out.call
  sign_in.call("kevin@37signals.com")
  cdp.navigate("#{BASE}/bots")
  final_text = cdp.eval_js("document.body.innerText")
  assert_eq true, final_text.include?("Beta Bot"), "Beta Bot preserved after lowering limit to 0"
  assert_eq true, final_text.include?("Gamma Bot"), "Gamma Bot preserved after lowering limit to 0"
  assert_eq false, final_text.include?("Add a chat bot"), "member blocked at limit 0"
  assert_eq true, final_text.include?("reached the limit"), "member sees reached the limit at limit 0"

  puts "ALL REAL-BROWSER CHROMIUM CHECKS PASSED!"
ensure
  cdp&.close
  Process.kill("TERM", chrome_pid) rescue nil
  Process.kill("TERM", server_pid) rescue nil
  Process.wait(chrome_pid) rescue nil
  Process.wait(server_pid) rescue nil
  system("rm -rf /tmp/chrome_verify_profile /tmp/browser_verify.rb /tmp/rails_verify.log /tmp/chrome_verify.log")
end
